    "id": "heading:packages/codepot-openapi/schemas:shared-properties",
    "kind": "heading",
    "path": "packages/codepot-openapi/schemas",
    "href": "/docs/packages/codepot-openapi/schemas#shared-properties",
    "title": "Shared properties",
    "pageTitle": "Properties, schemas, and references",
